const r = $json;
const out = (r.stdout || '').trim();
const err = (r.stderr || '').trim();

if (r.code !== 0) {
  throw new Error('匹配脚本失败：' + err.split('\n').slice(-6).join(' | '));
}

const line = out.split('\n').find(l => l.startsWith('RESULT '));
if (!line) throw new Error('脚本没有输出 RESULT，原始输出：' + out.slice(-400));
const res = JSON.parse(line.slice(7));

return [{
  json: {
    ok: res.ok,
    order: res.order,
    orders: res.orders,
    rows: res.rows,
    steps: res.steps,
    missing: [...(res.missing_sku || []), ...(res.missing_rate || [])]
  }
}];

// 已有待补（未处理的）标识集合
const existing = new Set();
try {
  const it = $('③ 读待补表已有').first().json;
  for (const rec of (it.items || [])) {
    const f = rec.fields || {};
    const key = Array.isArray(f['标识']) ? f['标识'][0]?.text : f['标识'];
    const st = Array.isArray(f['状态']) ? f['状态'][0]?.name ?? f['状态'][0] : f['状态'];
    if (key) existing.add(String(key).trim());
  }
} catch (e) {}

const base = $('② 解析结果').first().json;
const todo = (base.missing || []).filter(m => !existing.has(String(m['标识']).trim()));

return [{
  json: {
    newCount: todo.length,
    totalMissing: (base.missing || []).length,
    skipped: (base.missing || []).length - todo.length,
    records: todo.map(m => ({
      fields: {
        '类型': m['类型'],
        '标识': m['标识'],
        '建议前缀': m['建议前缀'] || '',
        '订单数': m['订单数'] ?? 0,
        '行数': m['行数'] ?? 0,
        '样例交易编号': m['样例交易编号'] || '',
        'SKU样例': m['SKU样例'] || '',
        '说明': m['说明'] || '',
        '状态': '待处理'
      }
    })),
    steps: base.steps,
    order: base.order
  }
}];

const p = $('④ 过滤出新增').first().json;
return [{
  json: {
    ok: true,
    order: p.order,
    steps: p.steps,
    totalMissing: p.totalMissing,
    newWritten: p.newCount,
    skipped: p.skipped,
    message: p.newCount
      ? `新增 ${p.newCount} 条待补（已跳过 ${p.skipped} 条重复）`
      : `本轮没有新的待补项（已有 ${p.totalMissing} 条待补仍在表里）`
  }
}];

const p = $('④ 过滤出新增').first().json;
return [{
  json: {
    ok: true,
    order: p.order,
    steps: p.steps,
    totalMissing: 0,
    newWritten: 0,
    skipped: 0,
    message: '全部匹配成功，无需补填'
  }
}];
